// Chart Bar Type
const xAxisValues = []
const listHeader = []
const dataResult = []
const allData = data.series
const dataSet = data.series.map(b => b.data_set)
const allDataValue = dataSet.map(currentSet => {
  return currentSet.map(data => data)
})
// Create Header
allData.forEach(serie => {
  serie.data_set.forEach(set => {
      xAxisValues.push(set.name)
  })
})
// Grup Data
allData.forEach(serie => {
  serie.data_set.forEach(set => {
    if (!listHeader.find(value => value === set.name)) {
      const filterByLabel = serie.data_set.filter(b => b.name === set.name)
      const arrayValues = filterByLabel.map(b => b.value)
      const initialValue = 0
      const sumValues = arrayValues.reduce(
        (accumulator, currentValue) => accumulator + currentValue, initialValue
      )
      dataResult.push({ name: set.name, value: sumValues})
      listHeader.push(set.name)
    }
  })
})

const listSerie = allData.map((currentData, key) => {
  return {
    name: currentData.name,
    stack: 'vistors',
    barWidth: '60%',
    data: dataResult,
    smooth: true,
    type: 'bar',
    animationEasing: 'quadraticOut',
    lineStyle: {
      width: 2
    }
  }
})

return {
  xAxis: {
    data: listHeader,
    boundaryGap: true,
    axisTick: {
      show: false
    }
  },
  toolbox: {
    // y: 'bottom',
    feature: {
      magicType: {
        type: ['stack', 'tiled']
      },
      dataView: {},
      saveAsImage: {
        pixelRatio: 2
      }
    }
  },
  grid: {
    left: 10,
    right: 10,
